def smcrop(g, by='rows'):
    h,w=len(g),len(g[0])
    if by=='cols':
        k=w//2+1
        while True:
            sub=[r[:k] for r in g]
            if all(all(sub[i][j]==g[i][j%k] for j in range(w)) for i in range(h)): return sub
            k-=1; break
    else:
        k=h//2+1
        while True:
            sub=[r[:k] for r in g]
            if all(all(sub[i][j]==g[(i+j)%k][j] for j in range(w)) for i in range(h)): return sub
            k-=1; break

